package cn.zhuatech.audit.deep;import cn.zhuatech.audit.common.ApiResponse;import jakarta.validation.Valid;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/audit-ops") public class DeepDomainController{private final DeepDomainService s;public DeepDomainController(DeepDomainService s){this.s=s;}@GetMapping("/dashboard")ApiResponse<?> dashboard(@RequestParam String organizationCode){return ApiResponse.ok(s.dashboard(organizationCode));}@PostMapping("/engagements")ApiResponse<?> create(@Valid @RequestBody DeepDomainService.EngagementRequest r){return ApiResponse.ok(s.create(r));}@PostMapping("/engagements/{id}/start")ApiResponse<?> start(@PathVariable Long id){return ApiResponse.ok(s.start(id));}@PostMapping("/engagements/{id}/workpapers")ApiResponse<?> paper(@PathVariable Long id,@Valid @RequestBody DeepDomainService.WorkpaperRequest r){return ApiResponse.ok(s.addWorkpaper(id,r));}@PostMapping("/workpapers/{id}/submit")ApiResponse<?> submit(@PathVariable Long id){return ApiResponse.ok(s.submitPaper(id));}@PostMapping("/engagements/{id}/findings")ApiResponse<?> finding(@PathVariable Long id,@Valid @RequestBody DeepDomainService.FindingRequest r){return ApiResponse.ok(s.createFinding(id,r));}@PostMapping("/findings/{id}/action-plan")ApiResponse<?> plan(@PathVariable Long id,@Valid @RequestBody DeepDomainService.ActionPlanRequest r){return ApiResponse.ok(s.plan(id,r));}@PostMapping("/findings/{id}/remediate")ApiResponse<?> remediate(@PathVariable Long id,@Valid @RequestBody DeepDomainService.EvidenceRequest r){return ApiResponse.ok(s.remediate(id,r));}}
